from pyfsr import FortiSOAR

client = FortiSOAR(
    base_url="https://fortisoar.example.com",
    username="<user>",
    password="<password>",
)

alert = client.records("alerts").update(
    "9f0eb603-ac1e-41c3-b47b-444589beed39", {"description": "Escalated"}
)
print(alert.name)

